"""Running usage total reported to the Acme billing API.

The total accumulates as a normal Python integer (arbitrary precision, so effectively
64-bit-and-beyond), fixing INC-7701: the previous signed 32-bit mask (`_to_int32`) wrapped the
total to a negative value once an account accumulated past 2^31 units, and billing underbilled
the account.
"""


class UsageCounter:
    def __init__(self, start=0):
        self._total = int(start)

    def add(self, units):
        self._total += units   # no 32-bit mask: the total grows past 2^31 instead of wrapping

    @property
    def total(self):
        return self._total

